AS        
BEGIN
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
	SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET ANSI_WARNINGS OFF;

    -- LOG 용 
	DECLARE @V_USER_ID_sim   NVARCHAR(150) = N'';  
    DECLARE @v_program_name NVARCHAR(150) = N'PR_SCP_XLS_ADD_SMALL';
    DECLARE @n_log_count		INTEGER = 0;
    DECLARE @v_log_message	NVARCHAR(1000);
    DECLARE @v_description	 NVARCHAR(500);     
    DECLARE @v_table_id		 VARCHAR(150) = N'SCP_XLS_PSI_GLOBAL_SMALL'; 
    DECLARE @d_event_date   DATETIME;
    DECLARE @v_start_time   DATETIME     = SYSDATETIME();                
    DECLARE @v_exec_time    NVARCHAR(10) = ''--'[00:00]';        

	-- 작업용 변수
	DECLARE @v_xls_key1	INT;
	DECLARE @v_batch_create_to_yyyymmdd      NVARCHAR(8);

	--초기화
	SELECT  @v_xls_key1 = CAST(@P_XLS_KEY1 AS INT) , @v_batch_create_to_yyyymmdd  =  DBO.FN_XLS_DATE(@P_CREATE_FROM_YYYYMMDD, 363)
	           , @V_USER_ID_sim = @P_USER_ID + '[SIMULATION]' -- UI 작업자와 시물레이션 작업자를 구분하기 위해서

    -- 시작 LOG
    SELECT  @v_log_message = N'########## Start of procedure ##########',  @v_description = @v_program_name + ':' + N' SCP_XLS_PSI_GLOBAL_SMALL SAVE LOGIC',     @d_event_date = SYSDATETIME();
	IF @P_IS_DEBUG = 0 EXEC PR_SCP_SYS_LOG_BATCH  @v_program_name   , 'START' , @n_log_count  ,@v_log_message , @v_description ,@d_event_date , @P_USER_ID                              ;      

    BEGIN TRY

    -------------------------------------------------------------------------------------------------------------------------------------------------------         
     -- 입력된 버전과 현재 버전이 다를 경우 처리 생략
    -------------------------------------------------------------------------------------------------------------------------------------------------------
		if @P_PLAN_TYPE = 'FN'  RAISERROR ('PLAN TYPE "FN" CANNOT BE UPDATED', 10 , 1) --With a severity of 10 or lower in a TRY block.		
    -------------------------------------------------------------------------------------------------------------------------------------------------------         
    -- 입력된 버전과 현재 버전이 다를 경우 EXCEPTION 
    -------------------------------------------------------------------------------------------------------------------------------------------------------
        DECLARE   @v_division_id          NVARCHAR(030) = @P_DIVISION_ID
                , @v_plan_start_yyyymmdd  NVARCHAR(008) = @P_PLAN_START_YYYYMMDD
                , @v_plan_type            NVARCHAR(050) = @P_PLAN_TYPE
                , @v_seq                  INT           = @P_SEQ

        SELECT TOP 1  @v_division_id          = DIVISION_ID
                    , @v_plan_start_yyyymmdd  = PLAN_START_YYYYMMDD
                    , @v_plan_type            = PLAN_TYPE
                    , @v_seq                  = SEQ
          FROM SCP_XLS_PSI_GLOBAL_SMALL WITH (NOLOCK)

