		 RAISERROR ('PLAN DATA IS DIFFERENT FROM CURRENT PLAN  ', 11 , 1)	

       IF @P_MEASURE NOT  IN  ('SHIP_PLAN', 'CELL_PROD')    
	     RAISERROR ('PLAN DATA CANNOT BE SAVED WITH REQUESTED MEASURE ' , 11 , 1)	 

