			SET WQTY01 = QTY001+QTY002+QTY003+QTY004+QTY005+QTY006+QTY007,WQTY02 = QTY008+QTY009+QTY010+QTY011+QTY012+QTY013+QTY014,WQTY03 = QTY015+QTY016+QTY017+QTY018+QTY019+QTY020+QTY021,WQTY04 = QTY022+QTY023+QTY024+QTY025+QTY026+QTY027+QTY028,WQTY05 = QTY029+QTY030+QTY031+QTY032+QTY033+QTY034+QTY035,WQTY06 = QTY036+QTY037+QTY038+QTY039+QTY040+QTY041+QTY042,WQTY07 = QTY043+QTY044+QTY045+QTY046+QTY047+QTY048+QTY049,WQTY08 = QTY050+QTY051+QTY052+QTY053+QTY054+QTY055+QTY056,WQTY09 = QTY057+QTY058+QTY059+QTY060+QTY061+QTY062+QTY063,WQTY10 = QTY064+QTY065+QTY066+QTY067+QTY068+QTY069+QTY070,WQTY11 = QTY071+QTY072+QTY073+QTY074+QTY075+QTY076+QTY077,WQTY12 = QTY078+QTY079+QTY080+QTY081+QTY082+QTY083+QTY084,WQTY13 = QTY085+QTY086+QTY087+QTY088+QTY089+QTY090+QTY091,WQTY14 = QTY092+QTY093+QTY094+QTY095+QTY096+QTY097+QTY098,WQTY15 = QTY099+QTY100+QTY101+QTY102+QTY103+QTY104+QTY105,WQTY16 = QTY106+QTY107+QTY108+QTY109+QTY110+QTY111+QTY112,WQTY17 = QTY113+QTY114+QTY115+QTY116+QTY117+QTY118+QTY119,WQTY18 = QTY120+QTY121+QTY122+QTY123+QTY124+QTY125+QTY126,WQTY19 = QTY127+QTY128+QTY129+QTY130+QTY131+QTY132+QTY133,WQTY20 = QTY134+QTY135+QTY136+QTY137+QTY138+QTY139+QTY140,WQTY21 = QTY141+QTY142+QTY143+QTY144+QTY145+QTY146+QTY147,WQTY22 = QTY148+QTY149+QTY150+QTY151+QTY152+QTY153+QTY154,WQTY23 = QTY155+QTY156+QTY157+QTY158+QTY159+QTY160+QTY161,WQTY24 = QTY162+QTY163+QTY164+QTY165+QTY166+QTY167+QTY168,WQTY25 = QTY169+QTY170+QTY171+QTY172+QTY173+QTY174+QTY175,WQTY26 = QTY176+QTY177+QTY178+QTY179+QTY180+QTY181+QTY182,WQTY27 = QTY183+QTY184+QTY185+QTY186+QTY187+QTY188+QTY189,WQTY28 = QTY190+QTY191+QTY192+QTY193+QTY194+QTY195+QTY196,WQTY29 = QTY197+QTY198+QTY199+QTY200+QTY201+QTY202+QTY203,WQTY30 = QTY204+QTY205+QTY206+QTY207+QTY208+QTY209+QTY210,WQTY31 = QTY211+QTY212+QTY213+QTY214+QTY215+QTY216+QTY217,WQTY32 = QTY218+QTY219+QTY220+QTY221+QTY222+QTY223+QTY224,WQTY33 = QTY225+QTY226+QTY227+QTY228+QTY229+QTY230+QTY231,WQTY34 = QTY232+QTY233+QTY234+QTY235+QTY236+QTY237+QTY238,WQTY35 = QTY239+QTY240+QTY241+QTY242+QTY243+QTY244+QTY245,WQTY36 = QTY246+QTY247+QTY248+QTY249+QTY250+QTY251+QTY252,WQTY37 = QTY253+QTY254+QTY255+QTY256+QTY257+QTY258+QTY259,WQTY38 = QTY260+QTY261+QTY262+QTY263+QTY264+QTY265+QTY266,WQTY39 = QTY267+QTY268+QTY269+QTY270+QTY271+QTY272+QTY273,WQTY40 = QTY274+QTY275+QTY276+QTY277+QTY278+QTY279+QTY280,WQTY41 = QTY281+QTY282+QTY283+QTY284+QTY285+QTY286+QTY287,WQTY42 = QTY288+QTY289+QTY290+QTY291+QTY292+QTY293+QTY294,WQTY43 = QTY295+QTY296+QTY297+QTY298+QTY299+QTY300+QTY301,WQTY44 = QTY302+QTY303+QTY304+QTY305+QTY306+QTY307+QTY308,WQTY45 = QTY309+QTY310+QTY311+QTY312+QTY313+QTY314+QTY315,WQTY46 = QTY316+QTY317+QTY318+QTY319+QTY320+QTY321+QTY322,WQTY47 = QTY323+QTY324+QTY325+QTY326+QTY327+QTY328+QTY329,WQTY48 = QTY330+QTY331+QTY332+QTY333+QTY334+QTY335+QTY336,WQTY49 = QTY337+QTY338+QTY339+QTY340+QTY341+QTY342+QTY343,WQTY50 = QTY344+QTY345+QTY346+QTY347+QTY348+QTY349+QTY350,WQTY51 = QTY351+QTY352+QTY353+QTY354+QTY355+QTY356+QTY357,WQTY52 = QTY358+QTY359+QTY360+QTY361+QTY362+QTY363+QTY364
		WHERE  DIVISION_ID          = @P_DIVISION_ID
		AND CREATE_FROM_YYYYMMDD = @P_CREATE_FROM_YYYYMMDD
		AND XLS_KEY1             = @v_xls_key1    	

		IF @P_MEASURE IN  ('SHIP_PLAN')   
		BEGIN  -- SHIP PLAN 시작		  
			DECLARE @v_bod_from				NVARCHAR(12) = '';
			DECLARE @v_bod_to				NVARCHAR(12) = '';

			SELECT @v_bod_from = (CASE WHEN ATTRIBUTE3 IS NULL THEN '19900101' ELSE LEFT(ATTRIBUTE3, 8) END)
					,@v_bod_to   = (CASE WHEN ATTRIBUTE3 IS NULL THEN '29991231' ELSE RIGHT(ATTRIBUTE3, 8) END)
				FROM SCP_XLS_PSI_GLOBAL_SMALL WITH (NOLOCK)
				WHERE  DIVISION_ID          = @P_DIVISION_ID
				AND CREATE_FROM_YYYYMMDD = @P_CREATE_FROM_YYYYMMDD
				AND XLS_KEY1             = @v_xls_key1       
			;

		--변경데이터셋 
			INSERT @CHANGED_DATA 
			 SELECT A.TOKEN , CAST ( B.TOKEN AS NUMERIC(20,10)) 
			 FROM STRING_SPLIT(@YMD_STRINGS , ',') A
			 INNER	JOIN String_Split(@QTY_STRINGS,   ',') B
				ON A.NR = B.NR
			 WHERE B.TOKEN <> '-9'			 

			IF @P_IS_DEBUG = 1  SELECT '@CHANGED_DATA' as "@CHANGED_DATA",  * FROM @CHANGED_DATA 

		
			IF OBJECT_ID('tempdb..#SCP_ANL_SHIPMENT_PLAN_FG') IS NOT NULL	
			DROP TABLE #SCP_ANL_SHIPMENT_PLAN_FG				

			SELECT X.DIVISION_ID
						,X.PLAN_START_YYYYMMDD
						,X.PLAN_TYPE
						,X.SEQ
						,X.OPERATION_GROUP AS BIZ_TYPE
						,X.PROJECT_CODE
						,X.ITEM_ID
						,X.TO_SITE
						,X.INCOTERMS
						,X.FROM_SITE
						,X.BOD_ID
						,X.TRANSPORT_MODE
						,'SHIP_PLAN_AMEND' AS MEASURE 
						,Y.YYYYMMDD
						,Y.QTY
						,@P_DIVISION_ID  AS ORIGIN_FROM_DIVISION_ID		
						,@P_DIVISION_ID  AS ORIGIN_TO_DIVISION_ID			
						,'' AS ELECTRODE_TYPE
						,X.ATTRIBUTE1
				INTO #SCP_ANL_SHIPMENT_PLAN_FG
				FROM (SELECT * FROM SCP_XLS_PSI_GLOBAL_SMALL   WITH (NOLOCK) 
							WHERE  DIVISION_ID          = @P_DIVISION_ID
							AND CREATE_FROM_YYYYMMDD = @P_CREATE_FROM_YYYYMMDD
							AND XLS_KEY1             = @v_xls_key1  ) X			
                FULL JOIN  @CHANGED_DATA Y
					ON 1 = 1
				WHERE  Y.YYYYMMDD BETWEEN @v_bod_from AND @v_bod_to
				;
			 
			IF @P_IS_DEBUG = 1 SELECT '#SCP_ANL_SHIPMENT_PLAN_FG'   AS "#SCP_ANL_SHIPMENT_PLAN_FG",  * FROM #SCP_ANL_SHIPMENT_PLAN_FG--TEST
			
			MERGE INTO SCP_ANL_SHIPMENT_PLAN_FG AS X  
				USING  #SCP_ANL_SHIPMENT_PLAN_FG AS Y WITH(NOLOCK)
				ON 0 = 0
				AND X.DIVISION_ID               = Y.DIVISION_ID				--@P_DIVISION_ID			--  2021.10.25 튜닝개선요청에 따른 변경
				AND X.PLAN_START_YYYYMMDD       = Y.PLAN_START_YYYYMMDD		--@@P_PLAN_START_YYYYMMDD
				AND X.PLAN_TYPE                 = Y.PLAN_TYPE				--@P_PLAN_TYPE
				AND X.SEQ                       = Y.SEQ						--@P_SEQ                
				AND X.BIZ_TYPE                  = Y.BIZ_TYPE
				AND X.PROJECT_CODE              = Y.PROJECT_CODE
				AND X.ITEM_ID                   = Y.ITEM_ID
				AND X.TO_SITE                   = Y.TO_SITE
				AND X.INCOTERMS                 = Y.INCOTERMS
				AND X.FROM_SITE                 = Y.FROM_SITE
				AND X.BOD_ID                    = Y.BOD_ID                
				AND X.MEASURE                   = Y.MEASURE
				AND X.YYYYMMDD                  = Y.YYYYMMDD
				WHEN MATCHED  THEN 
				UPDATE 
					SET  X.QTY = Y.QTY
						,X.LAST_UPDATED_BY    = @V_USER_ID_sim
						,X.LAST_UPDATE_DATE   = GETDATE()
				WHEN NOT MATCHED  THEN                  
					INSERT (
								DIVISION_ID
								,PLAN_START_YYYYMMDD
								,PLAN_TYPE
								,SEQ
								,BIZ_TYPE
								,PROJECT_CODE
								,ITEM_ID
								,TO_SITE
								,INCOTERMS
								,FROM_SITE
								,BOD_ID
								,MEASURE 
								,YYYYMMDD
								,QTY
								,ORIGIN_FROM_DIVISION_ID
								,ORIGIN_TO_DIVISION_ID
								,ELECTRODE_TYPE
							,CREATED_BY
							,CREATION_DATE
							,LAST_UPDATED_BY
							,LAST_UPDATE_DATE
						)
					VALUES (
							Y.DIVISION_ID
							,Y.PLAN_START_YYYYMMDD
							,Y.PLAN_TYPE
							,Y.SEQ
							,Y.BIZ_TYPE
							,Y.PROJECT_CODE
							,Y.ITEM_ID
							,Y.TO_SITE
							,Y.INCOTERMS
							,Y.FROM_SITE
							,Y.BOD_ID
							,Y.MEASURE 
							,Y.YYYYMMDD
							,Y.QTY
							,Y.ORIGIN_FROM_DIVISION_ID
							,Y.ORIGIN_TO_DIVISION_ID
							,Y.ELECTRODE_TYPE
							,@V_USER_ID_sim
							,GETDATE()
							,@V_USER_ID_sim
							,GETDATE()
						)
					;						
		   
	
			IF @P_IS_DEBUG = 0
			INSERT INTO dbo.SCP_ANL_SHIPMENT_PLAN_FG_H
						(
						HISTORY_SEQ, DIVISION_ID
						,PLAN_START_YYYYMMDD
						,PLAN_TYPE
						,SEQ
						,BIZ_TYPE
						,PROJECT_CODE
						,ITEM_ID
						,TO_SITE
						,INCOTERMS
						,FROM_SITE
						,BOD_ID
						,MEASURE
						,YYYYMMDD
						,QTY
						,ORIGIN_TO_DIVISION_ID
						,ORIGIN_FROM_DIVISION_ID
						,ELECTRODE_TYPE
						,CREATED_BY
						,CREATION_DATE
						,LAST_UPDATED_BY
						,LAST_UPDATE_DATE
						,HISTORY_CREATION_DATE
						)
						SELECT 
						NEXT VALUE FOR SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H
						,DIVISION_ID
						,PLAN_START_YYYYMMDD
						,PLAN_TYPE
						,SEQ
						,BIZ_TYPE
						,PROJECT_CODE
						,ITEM_ID
						,TO_SITE
						,INCOTERMS
						,FROM_SITE
						,BOD_ID
						,MEASURE
						,YYYYMMDD
						,QTY
						,ORIGIN_TO_DIVISION_ID
						,ORIGIN_FROM_DIVISION_ID
						,ELECTRODE_TYPE
						,@V_USER_ID_sim 
						,GETDATE() 
						,@V_USER_ID_sim  
						,GETDATE()   
						,GETDATE()   
						FROM #SCP_ANL_SHIPMENT_PLAN_FG  WITH (NOLOCK) ;

			-- SCP_ANL_SHIPMENT_PLAN_FIX (수정)
			IF @P_IS_DEBUG = 0
			UPDATE X
					SET X.QTY               = Y.QTY
						,X.FIX_REASON    = 'SIMULATION UPDATE'
						,X.ATTRIBUTE1        = 'Y'       -- History 구분을 위해
						,X.LAST_UPDATED_BY   = @V_USER_ID_sim
						,X.LAST_UPDATE_DATE  = GETDATE()
					FROM SCP_ANL_SHIPMENT_PLAN_FIX  X WITH (NOLOCK)     -- FIX_ID, DIVISION_ID, BIZ_TYPE, ITEM_ID, TO_SITE, FROM_SITE, BOD_ID, YYYYMMDD
					INNER JOIN #SCP_ANL_SHIPMENT_PLAN_FG Y WITH (NOLOCK)
					ON 0 = 0
					AND X.DIVISION_ID = Y.DIVISION_ID
					AND X.BIZ_TYPE    = Y.BIZ_TYPE
					AND X.PROJECT_CODE= Y.PROJECT_CODE
					AND X.ITEM_ID     = Y.ITEM_ID
					AND X.TO_SITE     = Y.TO_SITE
					AND X.FROM_SITE   = Y.FROM_SITE
					AND X.BOD_ID      = Y.BOD_ID
					AND X.YYYYMMDD    = Y.YYYYMMDD   

			-------------------------------------------------------------------------------------------------------------         
			-- SCP_ANL_SHIPMENT_PLAN_FIX_H : FIX History 입력
			-------------------------------------------------------------------------------------------------------------         
			IF @P_IS_DEBUG = 0					
			INSERT INTO dbo.SCP_ANL_SHIPMENT_PLAN_FIX_H
						(
							HISTORY_SEQ
							,FIX_ID
							,DIVISION_ID
							,BIZ_TYPE
							,ITEM_ID
							,TO_SITE
							,FROM_SITE
							,PROJECT_CODE
							,INCOTERMS
							,BOD_ID
							,YYYYMMDD
							,QTY
							,FIX_REASON
							,ORIGIN_FROM_DIVISION_ID
							,ORIGIN_TO_DIVISION_ID
							,ELECTRODE_TYPE
							,CREATED_BY
							,CREATION_DATE
							,LAST_UPDATED_BY
							,LAST_UPDATE_DATE
							,HISTORY_CREATION_DATE
					)
					SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H --여러개 발생가능성
							,FIX_ID
							,DIVISION_ID
							,BIZ_TYPE
							,ITEM_ID
							,TO_SITE
							,FROM_SITE
							,PROJECT_CODE
							,INCOTERMS
							,BOD_ID
							,YYYYMMDD
							,QTY
							,FIX_REASON
							,ORIGIN_FROM_DIVISION_ID
							,ORIGIN_TO_DIVISION_ID
							,ELECTRODE_TYPE
							,@V_USER_ID_sim   
							,GETDATE()    AS CREATION_DATE
							,@V_USER_ID_sim   AS LAST_UPDATED_BY
							,GETDATE()    AS LAST_UPDATE_DATE
							,GETDATE()    AS HISTORY_CREATION_DATE
					FROM SCP_ANL_SHIPMENT_PLAN_FIX  WITH (NOLOCK)
					WHERE ATTRIBUTE1 =N'Y'

			-- FIX  수정
			IF @P_IS_DEBUG = 0
			UPDATE X
			SET X.ATTRIBUTE1 = NULL       -- History 구분을 위해 원상복구
			FROM SCP_ANL_SHIPMENT_PLAN_FIX  X WITH (NOLOCK)     -- FIX_ID, DIVISION_ID, BIZ_TYPE, ITEM_ID, TO_SITE, FROM_SITE, BOD_ID, YYYYMMDD
			INNER JOIN #SCP_ANL_SHIPMENT_PLAN_FG Y WITH (NOLOCK)
			ON 0 = 0
			AND X.DIVISION_ID = Y.DIVISION_ID
			AND X.BIZ_TYPE    = Y.BIZ_TYPE
			AND X.PROJECT_CODE= Y.PROJECT_CODE
			AND X.ITEM_ID     = Y.ITEM_ID
			AND X.TO_SITE     = Y.TO_SITE
			AND X.FROM_SITE   = Y.FROM_SITE
			AND X.BOD_ID      = Y.BOD_ID
			AND X.YYYYMMDD    = Y.YYYYMMDD  
			AND X.ATTRIBUTE1  ='Y'

		END --SHIP PLAN 종료

		IF @P_MEASURE IN  ('CELL_PROD')   
		BEGIN  -- CELL_PROD 시작
			INSERT @CHANGED_DATA  
			 SELECT A.TOKEN AS YYYYMMDD , CAST ( B.TOKEN AS NUMERIC(20,10))  AS QTY
			 FROM STRING_SPLIT(@YMD_STRINGS , ',') A
			 INNER	JOIN String_Split(@QTY_STRINGS,   ',') B
				ON A.NR = B.NR
			 WHERE B.TOKEN <> '-9'									

			IF @P_IS_DEBUG = 1  SELECT '@CHANGED_DATA' as "@CHANGED_DATA",  * FROM @CHANGED_DATA 
		
			IF OBJECT_ID('tempdb..#SCP_ANL_PRODUCTION_PLAN') IS NOT NULL	
			DROP TABLE #SCP_ANL_PRODUCTION_PLAN				

			SELECT X.DIVISION_ID
					, X.PLAN_START_YYYYMMDD
					, X.PLAN_TYPE
					 , X.SEQ
                      ,CONVERT(NVARCHAR(10), 'A') AS OPERATION_GROUP                    
                      ,X.FROM_SITE AS SCM_SITE_ID
                      ,X.ITEM_ID
                      ,X.PROD_LINE AS LINE_ID
                      ,X.ATTRIBUTE9 AS OPERATION_ID
                      ,'PROD_PLAN_AMEND' AS MEASURE
                      ,Y.YYYYMMDD
                      ,Y.QTY
                      ,X.DIVISION_ID AS ORIGIN_DIVISION_ID
                      ,''   AS ELECTRODE_TYPE
                      ,'0'   AS CELL_QTY           
				INTO #SCP_ANL_PRODUCTION_PLAN
				FROM (SELECT * FROM SCP_XLS_PSI_GLOBAL_SMALL   WITH (NOLOCK) 
							WHERE  DIVISION_ID          = @P_DIVISION_ID
							AND CREATE_FROM_YYYYMMDD = @P_CREATE_FROM_YYYYMMDD
							AND XLS_KEY1             = @v_xls_key1  ) X			
                FULL JOIN  @CHANGED_DATA Y
					ON 1 = 1
				--WHERE  Y.YYYYMMDD BETWEEN @v_bod_from AND @v_bod_to  FROZEN 구간 고려가능
				;
			 
			IF @P_IS_DEBUG = 1 SELECT '#SCP_ANL_PRODUCTION_PLAN'   AS "#SCP_ANL_PRODUCTION_PLAN",  * FROM #SCP_ANL_PRODUCTION_PLAN--TEST
			
			-- PROD_PLAN_AMEND


            INSERT INTO SCP_ANL_PRODUCTION_PLAN
                                     (DIVISION_ID
                                     ,PLAN_START_YYYYMMDD
                                     ,PLAN_TYPE
                                     ,SEQ
                                     ,OPERATION_GROUP
        --                             ,CELL_ITEM_ID
                                     ,SCM_SITE_ID
                                     ,ITEM_ID
                                     ,LINE_ID
                                     ,OPERATION_ID
                                     ,MEASURE
                                     ,YYYYMMDD
                                     ,QTY
                                     ,ORIGIN_DIVISION_ID
                                     ,ELECTRODE_TYPE
                                     ,CELL_QTY
                                     ,CREATED_BY
                                     ,CREATION_DATE
                                     ,LAST_UPDATED_BY
                                     ,LAST_UPDATE_DATE  
                                     )

                SELECT DIVISION_ID
                      ,PLAN_START_YYYYMMDD
                      ,PLAN_TYPE
                      ,SEQ
                      ,OPERATION_GROUP
                      ,SCM_SITE_ID
                      ,ITEM_ID
                      ,LINE_ID
                      ,OPERATION_ID
                      ,MEASURE
                      ,YYYYMMDD
                      ,QTY
                      ,ORIGIN_DIVISION_ID
                      ,ELECTRODE_TYPE
                      ,CELL_QTY
                      ,CREATED_BY
                      ,CREATION_DATE
                      ,LAST_UPDATED_BY
                      ,LAST_UPDATE_DATE  
                  FROM  
                  (   
                     			  MERGE INTO SCP_ANL_PRODUCTION_PLAN AS X  
                        USING (SELECT DIVISION_ID
                                     ,PLAN_START_YYYYMMDD
                                     ,PLAN_TYPE
                                     ,SEQ
                                     ,OPERATION_GROUP
                                     ,SCM_SITE_ID
                                     ,ITEM_ID
                                     ,LINE_ID
                                     ,OPERATION_ID
                                     ,MEASURE
                                     ,YYYYMMDD
                                     ,QTY
                                     ,ORIGIN_DIVISION_ID
                                     ,ELECTRODE_TYPE
                                     ,CELL_QTY
                                FROM #SCP_ANL_PRODUCTION_PLAN
                              ) AS Y
                        ON 0 = 0
                        AND X.DIVISION_ID         = Y.DIVISION_ID				--@p_division_id				-- 2021.10.25 튜닝개선요청에 따른 변경
                        AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD		--@p_PLAN_START_YYYYMMDD
                        AND X.PLAN_TYPE           = Y.PLAN_TYPE					--@p_PLAN_TYPE
                        AND X.SEQ                 = Y.SEQ						--@p_SEQ
                
                        AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                        AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                        AND X.ITEM_ID             = Y.ITEM_ID
                        AND X.MEASURE             = Y.MEASURE
                        AND X.YYYYMMDD            = Y.YYYYMMDD
                        AND X.LINE_ID             = Y.LINE_ID
                        AND X.OPERATION_ID        = Y.OPERATION_ID
                   AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                        AND X.ELECTRODE_TYPE      = Y.ELECTRODE_TYPE
            
                        WHEN MATCHED  THEN 
                        UPDATE 
                          SET  X.QTY = Y.QTY
                              ,X.LAST_UPDATED_BY    =@V_USER_ID_sim
                              ,X.LAST_UPDATE_DATE   = GETDATE()

                        WHEN NOT MATCHED THEN  
                          INSERT (
                                     DIVISION_ID
                                     ,PLAN_START_YYYYMMDD
                                     ,PLAN_TYPE
                                     ,SEQ
                                     ,OPERATION_GROUP
                                     ,SCM_SITE_ID
                                     ,ITEM_ID
                                     ,LINE_ID
                                     ,OPERATION_ID
                                     ,MEASURE
                                     ,YYYYMMDD
                                     ,QTY
                                     ,ORIGIN_DIVISION_ID
                                     ,ELECTRODE_TYPE
                                     ,CELL_QTY
                                    ,CREATED_BY
                                    ,CREATION_DATE
                                    ,LAST_UPDATED_BY
                                    ,LAST_UPDATE_DATE
                                )
                         VALUES (
                                   Y.DIVISION_ID
                                   ,Y.PLAN_START_YYYYMMDD
                                   ,Y.PLAN_TYPE
                                   ,Y.SEQ
                                   ,Y.OPERATION_GROUP
                                   ,Y.SCM_SITE_ID
                                   ,Y.ITEM_ID
                                   ,Y.LINE_ID
                                   ,Y.OPERATION_ID
                                   ,Y.MEASURE
                                   ,Y.YYYYMMDD
                                   ,Y.QTY
                                   ,Y.ORIGIN_DIVISION_ID
                                   ,Y.ELECTRODE_TYPE
                                   ,Y.CELL_QTY
                                  ,@V_USER_ID_sim
                                  ,GETDATE()
                                  ,@V_USER_ID_sim
                                  ,GETDATE()
                                ) 

                     -- INSERT 일경우 PROD_PLAN_ENGINE/PROD_PLAN_AMEND 쌍으로 입력한다.
                      OUTPUT $action, Inserted.DIVISION_ID
                                     ,Inserted.PLAN_START_YYYYMMDD
                                     ,Inserted.PLAN_TYPE
                                     ,Inserted.SEQ
                                     ,Inserted.OPERATION_GROUP
                                     ,Inserted.SCM_SITE_ID
                                     ,Inserted.ITEM_ID
                                     ,Inserted.LINE_ID
                                     ,Inserted.OPERATION_ID
                                     ,'PROD_PLAN_ENGINE' AS MEASURE
                                     ,Inserted.YYYYMMDD
                                     ,0  AS QTY
                                     ,Inserted.ORIGIN_DIVISION_ID
                                     ,Inserted.ELECTRODE_TYPE
                                     ,Inserted.CELL_QTY
                                     ,@V_USER_ID_sim AS CREATED_BY
                                     ,GETDATE() AS CREATION_DATE
                                     ,@V_USER_ID_sim AS LAST_UPDATED_BY
									,GETDATE() AS LAST_UPDATE_DATE                             
                        )

                        AS Changes ( Action
                                    ,DIVISION_ID
                                    ,PLAN_START_YYYYMMDD
                                    ,PLAN_TYPE
                                    ,SEQ
                                    ,OPERATION_GROUP
                                    ,SCM_SITE_ID
                                    ,ITEM_ID
                                    ,LINE_ID
                                    ,OPERATION_ID
                                    ,MEASURE
                                    ,YYYYMMDD
                                    ,QTY
                                    ,ORIGIN_DIVISION_ID
                                    ,ELECTRODE_TYPE
                                    ,CELL_QTY
                                    ,CREATED_BY
                                    ,CREATION_DATE
                                    ,LAST_UPDATED_BY
                                    ,LAST_UPDATE_DATE
                                    ) 
                        WHERE Action = 'INSERT' 
                                ;


			-- SCP_ANL_PRODUCTION_PLAN_H (등록)
				IF @P_IS_DEBUG = 0
				INSERT INTO dbo.SCP_ANL_PRODUCTION_PLAN_H
                      (
                        HISTORY_SEQ
                        ,DIVISION_ID
                        ,PLAN_START_YYYYMMDD
                        ,PLAN_TYPE
                        ,SEQ
                        ,OPERATION_GROUP
                        ,SCM_SITE_ID
                        ,ITEM_ID
                        ,LINE_ID
                        ,OPERATION_ID
                        ,MEASURE
                        ,YYYYMMDD
                        ,QTY
                        ,ORIGIN_DIVISION_ID
                        ,ELECTRODE_TYPE
                        ,CREATED_BY
                        ,CREATION_DATE
                        ,LAST_UPDATED_BY
                        ,LAST_UPDATE_DATE
                        ,HISTORY_CREATION_DATE
                      )
                      SELECT 
                        NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_H
                        ,DIVISION_ID
                        ,PLAN_START_YYYYMMDD
                        ,PLAN_TYPE
                        ,SEQ
                        ,OPERATION_GROUP
                        ,SCM_SITE_ID
                        ,ITEM_ID
                        ,LINE_ID
                        ,OPERATION_ID
                        ,MEASURE
                        ,YYYYMMDD
                        ,QTY
                        ,ORIGIN_DIVISION_ID
                        ,ELECTRODE_TYPE
                        ,@V_USER_ID_sim   AS CREATED_BY
                        ,GETDATE()    AS CREATION_DATE
                        ,@V_USER_ID_sim   AS LAST_UPDATED_BY
                        ,GETDATE()    AS LAST_UPDATE_DATE
                        ,GETDATE() AS HISTORY_CREATION_DATE
                       FROM #SCP_ANL_PRODUCTION_PLAN  WITH (NOLOCK)
					   ;
			
			IF @P_IS_DEBUG = 0
            UPDATE X
            SET  X.QTY              = Y.QTY
                ,X.ATTRIBUTE1       ='Y'
                ,X.LAST_UPDATED_BY  = @V_USER_ID_sim
                ,X.LAST_UPDATE_DATE = GETDATE()
            FROM SCP_ANL_PRODUCTION_PLAN_FIX  X WITH (NOLOCK)     -- FIX_ID, DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, YYYYMMDD
            INNER JOIN #SCP_ANL_PRODUCTION_PLAN Y WITH (NOLOCK)
            ON 0 = 0
            AND X.DIVISION_ID       = Y.DIVISION_ID
            AND X.OPERATION_GROUP   = Y.OPERATION_GROUP
            AND X.SCM_SITE_ID       = Y.SCM_SITE_ID
            AND X.ITEM_ID           = Y.ITEM_ID
            AND X.LINE_ID           = Y.LINE_ID
            AND X.OPERATION_ID      = Y.OPERATION_ID
            AND X.YYYYMMDD          = Y.YYYYMMDD 

			-------------------------------------------------------------------------------------------------------------         
			-- SCP_ANL_SHIPMENT_PLAN_FIX_H : FIX History 입력
			-------------------------------------------------------------------------------------------------------------         
			IF @P_IS_DEBUG = 0					
			  INSERT INTO dbo.SCP_ANL_PRODUCTION_PLAN_FIX_H
                      (
                          HISTORY_SEQ
                          ,FIX_ID
                          ,DIVISION_ID
                          ,OPERATION_GROUP
                          ,SCM_SITE_ID
                          ,ITEM_ID
                          ,LINE_ID
                          ,OPERATION_ID
                          ,YYYYMMDD
                          ,QTY
                          ,FIX_REASON
                          ,ORIGIN_DIVISION_ID
                          ,ELECTRODE_TYPE
                          ,CREATED_BY
                          ,CREATION_DATE
                          ,LAST_UPDATED_BY
                          ,LAST_UPDATE_DATE
                          --,ATTRIBUTE1
                          --,ATTRIBUTE2
                          --,ATTRIBUTE3
                          --,ATTRIBUTE4
                          --,ATTRIBUTE5
                          --,ATTRIBUTE6
                          --,ATTRIBUTE7
                          --,ATTRIBUTE8
                          --,ATTRIBUTE9
                          --,ATTRIBUTE10
                          ,HISTORY_CREATION_DATE
                    )

                    SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H
                          ,FIX_ID
                          ,DIVISION_ID
                          ,OPERATION_GROUP
                          ,SCM_SITE_ID
                          ,ITEM_ID
                          ,LINE_ID
                          ,OPERATION_ID
                          ,YYYYMMDD
                          ,QTY
                          ,FIX_REASON
                          ,ORIGIN_DIVISION_ID
                          ,ELECTRODE_TYPE
                          ,@V_USER_ID_sim   AS CREATED_BY
                          ,GETDATE()    AS CREATION_DATE
                          ,@V_USER_ID_sim   AS LAST_UPDATED_BY
                          ,GETDATE()    AS LAST_UPDATE_DATE
                        ,GETDATE()    AS HISTORY_CREATION_DATE
                   FROM SCP_ANL_PRODUCTION_PLAN_FIX  WITH (NOLOCK)
                  WHERE ATTRIBUTE1 = 'Y'

			-- FIX  수정
			IF @P_IS_DEBUG = 0
              UPDATE X
                    SET X.ATTRIBUTE1 = NULL       -- History 구분을 위해 원상복구
                    FROM SCP_ANL_PRODUCTION_PLAN_FIX  X WITH (NOLOCK)     -- FIX_ID, DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, YYYYMMDD
                    INNER JOIN #SCP_ANL_PRODUCTION_PLAN Y WITH (NOLOCK)
                    ON 0 = 0
                    AND X.DIVISION_ID     = Y.DIVISION_ID
                    AND X.OPERATION_GROUP = Y.OPERATION_GROUP
                    AND X.SCM_SITE_ID     = Y.SCM_SITE_ID
                    AND X.ITEM_ID         = Y.ITEM_ID
                    AND X.LINE_ID         = Y.LINE_ID
                    AND X.OPERATION_ID    = Y.OPERATION_ID
                    AND X.YYYYMMDD        = Y.YYYYMMDD
                    AND X.ATTRIBUTE1      =N'Y'

	 END --CELL PROD 종료

       -----------------------------------------------------------
        -- 실행 Logic END --
        -----------------------------------------------------------
        SELECT  @v_log_message = N'INSERT INTO '+@v_table_iD, @d_event_date = SYSDATETIME()
		IF @P_IS_DEBUG = 0 EXEC PR_SCP_SYS_LOG_BATCH  @v_program_name  , 'TXN' , @@ROWCOUNT  , @v_log_message , @v_description , @d_event_date  , @P_USER_ID                              ;				
    END TRY

    BEGIN CATCH             
		SELECT  @v_log_message = CAST(ERROR_MESSAGE() AS NVARCHAR(1000)), @v_description =  N'ERROR_LINE : ' + STR(ERROR_LINE()) , @d_event_date = SYSDATETIME()
		IF @P_IS_DEBUG = 0 EXEC PR_SCP_SYS_LOG_BATCH  @v_program_name  , 'ERROR' , @@ROWCOUNT  , @v_log_message , @v_description , @d_event_date  , @P_USER_ID                             
    END CATCH;

    --    임시 운영반영시에 주석처리 할것.                
     SET @v_exec_time  =  REPLICATE('0',2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) + ':' +                 
                          REPLICATE('0',2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60)) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60))                     
	-- 종료 LOG
    SELECT @v_log_message = N'########## END of procedure ##########', @d_event_date = SYSDATETIME()
			,  @v_description = N'['+@P_DIVISION_ID+']['+@P_PLAN_START_YYYYMMDD+']['+@P_MEASURE+']['+str(@v_xls_key1)+'][' + @v_exec_time + ']';         
    IF @P_IS_DEBUG = 0 EXEC PR_SCP_SYS_LOG_BATCH  @v_program_name   , 'END' , @@ROWCOUNT  ,@v_log_message , @v_description ,@d_event_date , @P_USER_ID                              ;

	RETURN 0;
  END; --BODY
